export interface Symptom {
  id: string;
  label: string;
  category: string;
  isRedFlag: boolean;
  redFlagMessage?: string;
}

export interface Condition {
  id: string;
  label: string;
}

export interface CurrentMedication {
  id: string;
  label: string;
}

export interface AllergyItem {
  id: string;
  label: string;
}

export interface DrugInteraction {
  withMed: string;
  effect: string;
  severity: "mild" | "moderate" | "severe";
}

export interface MedicationRule {
  id: string;
  name: string;
  brandExamples: string;
  category: string;
  mechanism: string;
  forSymptoms: string[];
  dosage: {
    adult: string;
    pediatric?: string;
    elderly?: string;
    maxDaily: string;
    frequency: string;
    withFood: boolean;
    duration: string;
    notes?: string;
  };
  contraindications: {
    conditions: string[];
    medications: string[];
    allergies: string[];
    pregnancy: "safe" | "caution" | "avoid";
    pregnancyNote?: string;
    minAge: number;
    elderlyRisk: "safe" | "caution" | "avoid";
    elderlyNote?: string;
  };
  interactions: DrugInteraction[];
  counselingPoints: string[];
  patientExplanation: string;
  referralIfNoImprovement: string;
  source: string;
}

