   150→      ...chronicConditions.map((c: string) => c.toLowerCase())
   151→    ].filter(Boolean);
   152→
   153→    if (med.indications?.some(indication => 
   154→      patientConditions.some(condition => 
   155→        condition.includes(indication.toLowerCase()) || 
   156→        indication.toLowerCase().includes(condition)
   157→      )
   158→    )) {
   159→      isRecommended = true;
   160→    }
   161→
   162→    // Check contraindications
   163→    if (med.contraindications?.some(contraindication =>
   164→      chronicConditions.some((condition: string) => 
   165→        condition.toLowerCase().includes(contraindication.toLowerCase())
   166→      )
   167→    )) {
   168→      safetyLevel = "avoid";
   169→      clinicalNote = `Contraindicated due to ${chronicConditions.join(", ")}`;
   170→      continue;
   171→    }
   172→
   173→    // Check allergies
   174→    if (allergies.includes(med.genericName?.toLowerCase() || "") ||
