   222→  const c = code.toUpperCase().replace(/\s/g, "");
   223→  if (c === "Z88.0") return "penicillin_allergy";
   224→  if (c === "Z88.1") return "penicillin_allergy";
   225→  if (c === "Z88.2") return "sulfonamide_allergy";
   226→  if (c === "Z88.3") return null;
   227→  if (c === "Z88.4") return null;
   228→  if (c === "Z88.5") return "opioid_allergy";
   229→  if (c === "Z88.6") return "nsaid_allergy";
   230→  if (c === "Z88.7") return null;
   231→  if (c === "Z88.8") return "other_drug_allergy";
   232→  if (c === "Z88.9") return "other_drug_allergy";
   233→  if (c.startsWith("Z88")) return "other_drug_allergy";
   234→  if (c.startsWith("T78.1")) return null;
   235→  if (c.startsWith("L23.3") || c.startsWith("L23.4")) return "latex_allergy";
   236→  return null;
